// ═══ VECTOR vs ARRAYLIST ═══
//
// Feature              Vector              ArrayList
// Thread-safe?         YES (all synced)    NO
// Performance          SLOW (lock overhead) FAST
// Growth               2x (doubles)         1.5x (50%)
// Since                Java 1.0             Java 1.2 (Collections FW)
// Enumeration          elements()           (Avoid) 
// Iterator             yes (fail-fast)      yes (fail-fast)
// Legacy methods       addElement, etc.     (Avoid) 
// Recommendation       DON'T USE            (Recommended) USE THIS

// ═══ WHY Vector is SLOW ═══
public class Vector<E> {
    public synchronized boolean add(E e) { ... }    // locked!
    public synchronized E get(int index) { ... }     // locked!
    public synchronized E remove(int index) { ... }  // locked!
    public synchronized int size() { ... }           // even SIZE is locked!
}
// Single-threaded: every call acquires/releases a lock → wasted overhead!
// Multi-threaded: entire Vector locked for each operation → bottleneck!

// ═══ MODERN ALTERNATIVES ═══
// Single-threaded: ArrayList (no locking overhead)
List<String> list = new ArrayList<>();

// Multi-threaded (simple): Collections.synchronizedList
List<String> syncList = Collections.synchronizedList(new ArrayList<>());

// Multi-threaded (read-heavy): CopyOnWriteArrayList
List<String> cowList = new CopyOnWriteArrayList<>();
// Reads: no lock! Writes: copy entire array (expensive but safe)

// ═══ GROWTH COMPARISON ═══
// Vector:    10 → 20 → 40 → 80 → 160 → 320 (doubles = 2x)
// ArrayList: 10 → 15 → 22 → 33 → 49 → 73  (1.5x)
// Vector wastes MORE memory (overshoots by 2x each time)
// Vector allows custom increment: new Vector<>(10, 5) → grows by 5 each time

// ═══ Stack extends Vector — also legacy! ═══
Stack<String> stack = new Stack<>();  // DON'T USE! Extends Vector.
Deque<String> stack = new ArrayDeque<>();  // (Recommended) USE THIS instead!
