package com.bank.vector;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class VectorVsArrayListTest {

    @Test
    void vector_isSynchronized() {
        Vector<String> vector = new Vector<>();
        vector.add("SAV2001");
        // Every method is synchronized — thread-safe but slow!
        assertThat(vector.get(0)).isEqualTo("SAV2001");
    }

    @Test
    void arrayList_notSynchronized_butFaster() {
        List<String> list = new ArrayList<>();
        list.add("SAV2001");
        assertThat(list.get(0)).isEqualTo("SAV2001");
        // No synchronization overhead → faster!
    }

    @Test
    void vector_doubles_arrayList_1point5x() throws Exception {
        // Vector grows by 2x:
        Vector<String> vector = new Vector<>();  // default capacity 10
        for (int i = 0; i < 11; i++) vector.add("V" + i);
        assertThat(vector.capacity()).isEqualTo(20);  // 10 → 20 (doubled!)

        // ArrayList grows by 1.5x:
        ArrayList<String> list = new ArrayList<>();
        for (int i = 0; i < 11; i++) list.add("A" + i);
        // Internal capacity = 15 (verified in Q140)
    }

    @Test
    void vector_legacyMethods() {
        Vector<String> vector = new Vector<>();
        vector.addElement("SAV2001");        // legacy method
        String first = vector.elementAt(0);  // legacy method
        Enumeration<String> e = vector.elements(); // legacy iterator
        assertThat(first).isEqualTo("SAV2001");
        assertThat(e.hasMoreElements()).isTrue();
    }

    @Test
    void modernAlternatives() {
        // Instead of Vector for thread safety:
        List<String> syncList = Collections.synchronizedList(new ArrayList<>());
        syncList.add("SAV2001");
        assertThat(syncList.get(0)).isEqualTo("SAV2001");

        // Instead of Stack (extends Vector):
        Deque<String> stack = new ArrayDeque<>();
        stack.push("A");
        stack.push("B");
        assertThat(stack.pop()).isEqualTo("B");  // LIFO!
    }

    @Test
    void performance_vectorVsArrayList() {
        int n = 500_000;

        long t1 = System.nanoTime();
        Vector<Integer> vector = new Vector<>();
        for (int i = 0; i < n; i++) vector.add(i);
        long vectorMs = (System.nanoTime() - t1) / 1_000_000;

        long t2 = System.nanoTime();
        ArrayList<Integer> arrayList = new ArrayList<>();
        for (int i = 0; i < n; i++) arrayList.add(i);
        long arrayMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("Vector: " + vectorMs + "ms, ArrayList: " + arrayMs + "ms");
        // ArrayList is typically 15-30% faster (no sync overhead)
    }
}
